<script lang="ts">
  import PixelRoom from '../components/PixelRoom.svelte';
  import CompanionPortrait from '../components/CompanionPortrait.svelte';
  import PixelIcon from '../components/PixelIcon.svelte';
  import { tick,onMount } from 'svelte';
  import { DBState,selectedCharID } from '../../ts/stores.svelte';
  import { chatState,selectCharacter,newConversation,selectConversation,sendMessage,stopMessage,deleteConversation,sourceOf,syncPersonalLore,analyzeChat } from '../bridge.svelte';
  import { companion,updateData,notify } from '../state.svelte';
  import { addMemory,visibleReply } from '../domain';
  import {interfaceState} from '../interfaceState.svelte';
  import ConfirmDialog from '../components/ConfirmDialog.svelte';
  import MarkdownIt from 'markdown-it';
  import DOMPurify from 'dompurify';
  let arrived=$state(!!interfaceState.roomArrival);
  onMount(()=>{if(interfaceState.chatDraft){draft=interfaceState.chatDraft;interfaceState.chatDraft='';void tick().then(()=>document.querySelector<HTMLTextAreaElement>('#message-input')?.focus({preventScroll:true}));}if(interfaceState.roomArrival){interfaceState.roomArrival=0;void tick().then(()=>document.querySelector<HTMLTextAreaElement>('#message-input')?.focus({preventScroll:true}));}});
  let sceneHidden=$state(false),historyOpen=$state(false);
  let view=$derived(companion.data.preferences.chatView==='theatre'?'theatre':'table');
  function changeView(value:'table'|'theatre'){try{updateData(data=>data.preferences.chatView=value);historyOpen=false;followMessages=true;}catch(e){notify(String(e));}}
  function showModelSettings(){location.hash='/settings';}
  let draft=$state(''),toDelete=$state(-1),listOpen=$state(false),messagesElement=$state<HTMLElement>();
  let followMessages=true;
  function trackScroll(event:Event){const el=event.currentTarget as HTMLElement;followMessages=el.scrollHeight-el.clientHeight-el.scrollTop<12;}
  let char=$derived(DBState.db.characters[$selectedCharID]);let chat=$derived(char?.chats[char.chatPage]);
  let currentRound=$derived.by(()=>{const messages=chat?.message.filter(m=>!m.isComment)||[];const index=messages.findLastIndex(m=>m.role==='user');return index<0?messages.slice(-1):messages.slice(index);});
  let speaking=$derived(chatState.busy&&chat?.message.at(-1)?.role==='char'&&!!chat?.message.at(-1)?.data);
  const markdown=new MarkdownIt({html:false,breaks:true,linkify:false});
  function rendered(text:string,role:string){return DOMPurify.sanitize(markdown.render(role==='char'?visibleReply(text):String(text||'')));}
  async function send(){const value=draft;if(!value.trim())return;draft='';followMessages=true;try{await sendMessage(value);}catch(e){notify(String(e));}await tick();if(followMessages)messagesElement?.scrollTo({top:messagesElement.scrollHeight,behavior:companion.data.preferences.reduceMotion||matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
  function remember(text:string,messageId:string){try{updateData(data=>addMemory(data,text,'important',true,sourceOf(messageId)));syncPersonalLore();notify('这段话已保存，可在记忆页查看和删除。');}catch(e){notify(String(e).replace(/^Error: /,''));}}
  $effect(()=>{chat?.id;followMessages=true;});
  $effect(()=>{const count=chat?.message.length;const text=chat?.message.at(-1)?.data;const list=messagesElement;if(count)void tick().then(()=>{if(list&&followMessages)list.scrollTo({top:list.scrollHeight});});});
  $effect(()=>{const list=messagesElement;if(!list)return;const resize=new ResizeObserver(()=>{if(followMessages)list.scrollTo({top:list.scrollHeight});});resize.observe(list);return()=>resize.disconnect();});
</script>
<div class="chat-heading xy-page-heading"><div><h1>说给小屿听</h1><p>{view==='theatre'?'一间亮着灯的小屋，和一段属于你的对话。':'像坐在同一张桌边，有话可以慢慢说。'}</p></div><div class="room-page-actions"><div class="chat-view-switch xy-tabs" aria-label="陪伴模式"><button type="button" class:chosen={view==='table'} aria-pressed={view==='table'} onclick={()=>changeView('table')}>同桌陪伴</button><button type="button" class:chosen={view==='theatre'} aria-pressed={view==='theatre'} onclick={()=>changeView('theatre')}>沉浸剧场</button></div><button type="button" class="xy-btn" aria-expanded={listOpen} onclick={()=>listOpen=!listOpen}>对话与功能</button><a class="text-link" href="#/">回到小岛</a></div></div>
{#snippet messageCard(message,index)}
 <article class="message-row" class:from-user={message.role==='user'}>{#if message.role==='user'}<PixelIcon src='/xinyu/art/nav_9.png' size={24}/>{:else}<span class="message-portrait"><CompanionPortrait tone={companion.data.preferences.avatar}/></span>{/if}<div class="message-wrap"><span class="message-name">{message.role==='user'?(companion.data.preferences.name||'我'):(DBState.db.characters.find(item=>item.chaId===message.saying)?.name||char?.name||'小屿')}{#if message.time}<time>{new Date(message.time).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</time>{/if}</span><div class="message-bubble">{@html rendered(message.data,message.role)}</div>{#if companion.data.preferences.memoryEnabled}<button class="remember-link" onclick={()=>remember(message.role==='char'?visibleReply(message.data):message.data,message.chatId)}>保存为记忆</button>{/if}</div></article>
{/snippet}
<div class="xy-chat-layout companion-layout" class:list-open={listOpen} class:room-arrival={arrived} data-chat-view={view}>
 {#if listOpen}<aside class="conversation-list xy-panel"><div class="panel-title"><h2>我的对话</h2><button class="icon-btn" aria-label="新建对话" onclick={newConversation} disabled={chatState.busy}><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg></button></div><label class="sr-only" for="chat-character">陪伴角色</label><select id="chat-character" value={$selectedCharID} onchange={(e)=>selectCharacter(Number(e.currentTarget.value))} disabled={chatState.busy}>{#each DBState.db.characters as character,index}<option value={index}>{character.name||'未命名角色'}{character.type==='group'?' · 群聊':''}</option>{/each}</select>
 <div class="conversation-items">{#each char?.chats||[] as conversation,index}<div class:chosen={char.chatPage===index} class="conversation-item"><button disabled={chatState.busy} onclick={()=>{selectConversation(index);historyOpen=false;}}><span class="conversation-icon">···</span><span><strong>{conversation.name||'未命名对话'}</strong><small>{conversation.message.length?visibleReply(conversation.message.at(-1).data).slice(0,30):'从一句你好开始'}</small></span></button><button class="delete-conversation" disabled={chatState.busy} aria-label={'删除对话 '+conversation.name} onclick={()=>toDelete=index}><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div>{/each}</div>
 <nav class="room-module-links" aria-label="房间里的功能"><a href="#/emotion">心情与回看</a><a href="#/memories">我们的记忆</a><a href="#/profile">陪伴档案</a><a href="#/growth">一起成长</a><a href="#/avatar">小屿衣橱</a><a href="#/scenes">窗外风景</a></nav><a class="original-link" href="#/settings">陪伴设置 →</a></aside>{/if}
 <div class="conversation-world" class:scene-hidden={sceneHidden} class:theatre-world={view==='theatre'} class:history-open={historyOpen}>
  <div class="companion-room" class:reading-backdrop={sceneHidden} aria-label="小屿的陪伴房间" aria-hidden={sceneHidden} inert={sceneHidden}><PixelRoom panorama={view==='theatre'||sceneHidden} decorative={sceneHidden} scene={companion.data.preferences.scene} avatar={companion.data.preferences.avatar} reduced={companion.data.preferences.reduceMotion} sound={companion.data.preferences.sound} {speaking} viewportInset={view==='theatre'||sceneHidden?0:.55} compact/>{#if !sceneHidden}<div class="scene-caption"><span class="scene-presence" aria-hidden="true"></span><div><strong>小屿在你身边</strong><span>{speaking?'小屿正在回应你':chatState.busy?'小屿正在认真听':'一起慢慢说，不必着急'}</span></div></div>{/if}</div>
  <section class="chat-main"><header class="chat-top"><span class="chat-top-portrait"><CompanionPortrait tone={companion.data.preferences.avatar}/></span><div><h2>{char?.name||'小屿'}</h2><span><i></i>{speaking?'正在回应你':chatState.busy?'正在认真听':'在这里，陪你慢慢说'}</span></div><div class="chat-quick-actions">{#if view==='theatre'}<button class="text-link" type="button" aria-expanded={historyOpen} onclick={()=>historyOpen=!historyOpen}>{historyOpen?'回到当前问答':'展开对话记录'}</button>{/if}<button class="text-link" type="button" aria-expanded={!sceneHidden} onclick={()=>sceneHidden=!sceneHidden}>{sceneHidden?'展开房间画面':'收起房间画面'}</button><button class="text-link" type="button" onclick={showModelSettings}>模型设置</button><button class="icon-btn" type="button" disabled={chatState.busy||!chat} aria-label={'删除对话 '+(chat?.name||'')} title="删除当前对话" onclick={()=>toDelete=char.chatPage}><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14M10 10v7m4-7v7"/></svg></button></div></header>
   {#if view==='table'||historyOpen}<div class="message-list" bind:this={messagesElement} onscroll={trackScroll} role="log" aria-label="对话消息" aria-live="polite" aria-relevant="additions">
    {#if !chat?.message.length}<div class="chat-welcome"><span class="welcome-pixel" aria-hidden="true">···</span><h2>今天的故事，从你开始。</h2><p>{char?.firstMessage||'你好，我在听。有什么想分享的吗？'}</p></div>{/if}
    {#each chat?.message||[] as message,index (message.chatId||index)}{#if !message.isComment}{@render messageCard(message,index)}{/if}{/each}
    {#if chatState.busy}<p class="thinking" role="status">{speaking?'小屿正在回应':'小屿正在认真听你说'}<span>···</span></p>{/if}
   </div>{:else}<div class="theatre-present" bind:this={messagesElement} onscroll={trackScroll} role="log" aria-label="当前一轮问答" aria-live="polite" aria-relevant="additions">{#if !currentRound.length}<div class="chat-welcome"><h2>小屋的灯，为你亮着。</h2><p>{char?.firstMessage||'你好，我在听。有什么想分享的吗？'}</p></div>{:else}{#each currentRound as message,index (message.chatId||index)}{@render messageCard(message,index)}{/each}{/if}{#if chatState.busy}<p class="thinking" role="status">{speaking?'小屿正在回应':'小屿正在认真听你说'}<span>···</span></p>{/if}</div>{/if}
   {#if chatState.error}<div class="chat-error" role="alert"><p>{chatState.error}</p><button class="xy-btn" onclick={()=>sendMessage('',true)} disabled={chatState.busy}>重试这条消息</button><button type="button" class="text-link" onclick={showModelSettings}>检查模型设置</button></div>{/if}
   <form class="chat-composer" aria-busy={chatState.busy} onsubmit={(e)=>{e.preventDefault();void send();}}><label for="message-input" class="sr-only">想对小屿说的话</label><textarea id="message-input" rows="2" bind:value={draft} maxlength="12000" placeholder="把今天的心情，轻轻放在这里…" onkeydown={(e)=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();if(!chatState.busy)void send();}}}></textarea><div class="composer-bottom"><span>Enter 发送 · Shift + Enter 换行</span>{#if chatState.busy}<button class="xy-btn" type="button" onclick={stopMessage}>停止回复</button>{:else}<button class="xy-btn primary" disabled={!draft.trim()} type="submit">发送 <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M12 19V5m-6 6 6-6 6 6"/></svg></button>{/if}</div></form>
  </section>
 </div>
</div>
{#if toDelete>=0}<ConfirmDialog destructive confirmText="确认删除" title="删除这段对话？" description="对话、关联的情绪/记忆/画像和相关旧版本将被删除；也会清理本机历史备份。此操作无法撤销。" onclose={()=>toDelete=-1} onconfirm={()=>deleteConversation(toDelete)}/>{/if}
